//! Measures the comparison at 2, 8 and 18 Mpixel.
//!
//! The fixtures under `benches/fixtures` are committed and generated by
//! `tools/fixtures/bench.mjs`. Decoding happens once per size and is not part
//! of what is timed: the crate compares decoded buffers.
//!
//! Each size is measured in three configurations, because they exercise
//! different amounts of work:
//!
//! - `identical`: both sides are the same buffer, so no pixel reaches the
//!   anti-aliasing detector. This is the throughput of the color metric alone.
//! - `aa-off`: the pair, with the detector disabled.
//! - `aa-on`: the pair, with the detector at its default. The difference
//!   against `aa-off` is what the detector costs.

use std::fs::File;
use std::io::BufReader;
use std::path::{Path, PathBuf};

use criterion::{criterion_group, criterion_main, BenchmarkId, Criterion, Throughput};
use pixeldelta_core::{compare, CompareOptions, Image};

/// Decoded RGBA8 pixels of a fixture.
struct Decoded {
    width: u32,
    height: u32,
    data: Vec<u8>,
}

impl Decoded {
    fn image(&self) -> Image<'_> {
        Image::from_rgba8(self.width, self.height, &self.data).expect("fixture wraps")
    }
}

fn fixtures_dir() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("benches/fixtures")
}

fn decode(path: &Path) -> Decoded {
    let mut decoder = png::Decoder::new(BufReader::new(
        File::open(path).expect("fixture is readable"),
    ));
    decoder.set_transformations(png::Transformations::ALPHA | png::Transformations::EXPAND);
    let mut reader = decoder.read_info().expect("fixture is a PNG");
    let mut data = vec![0; reader.output_buffer_size().expect("size fits in memory")];
    let info = reader.next_frame(&mut data).expect("fixture decodes");
    data.truncate(info.buffer_size());
    Decoded {
        width: info.width,
        height: info.height,
        data,
    }
}

fn bench_compare(c: &mut Criterion) {
    let mut group = c.benchmark_group("compare");
    // Reading two 18 Mpixel buffers per iteration puts the default sample size
    // in the minutes. Twenty samples still separate changes worth acting on.
    group.sample_size(20);

    for size in ["2mpx", "8mpx", "18mpx"] {
        let dir = fixtures_dir().join(size);
        let base = decode(&dir.join("base.png"));
        let head = decode(&dir.join("head.png"));
        let (a, b) = (base.image(), head.image());

        group.throughput(Throughput::Elements(a.pixel_count()));
        for (case, right, detect_antialiasing) in [
            ("identical", &a, true),
            ("aa-off", &b, false),
            ("aa-on", &b, true),
        ] {
            let opts = CompareOptions {
                threshold: 0.1,
                detect_antialiasing,
                ..CompareOptions::default()
            };
            group.bench_with_input(BenchmarkId::new(case, size), &opts, |bencher, opts| {
                bencher.iter(|| compare(std::hint::black_box(&a), right, opts));
            });
        }
    }

    group.finish();
}

criterion_group!(benches, bench_compare);
criterion_main!(benches);
